   9 /**
  10  * Get current session (server-side)
  11  */
  12 export async function getSession() {
  13   return await getServerSession(authOptions);
  14 }
  15 
  16 /**
  17  * Get current user (server-side)
  18  */
  19 export async function getCurrentUser() {
  20   const session = await getSession();
  21   
  22   if (!session?.user?.id) {
  23     return null;
  24   }
  25 
  26   const user = await prisma.user.findUnique({
  27     where: { id: session.user.id },
  28     select: {
  29       id: true,
  30       email: true,
  31       name: true,
  32       fullName: true,
  33       image: true,
  34       role: true,
  35       credits: true,
  36       phone: true,
  37       emailVerified: true,
  38       phoneVerified: true,
  39       createdAt: true,
  40       updatedAt: true,
  41       lastLoginAt: true,
  42     },
  43   });
  44 
  45   return user;
  46 }
  47 
  48 /**
  49  * Require authentication (server-side)
  50  * Throws error if not authenticated
  51  */
  52 export async function requireAuth() {
  53   const session = await getSession();
  54   
  55   if (!session?.user) {
  56     throw new Error('Unauthorized');
  57   }
  58 
  59   return session;
  60 }
  61 
  62 /**
  63  * Require admin role (server-side)
  64  * Throws error if not admin
  65  */
  66 export async function requireAdmin() {
  67   const user = await getCurrentUser();
  68   
  69   if (!user) {
  70     throw new Error('Unauthorized');
  71   }
  72 
  73   if (user.role !== 'ADMIN' && user.role !== 'SUPER_ADMIN') {
  74     throw new Error('Forbidden: Admin access required');
  75   }
  76 
  77   return user;
  78 }
  79 
  80 /**
  81  * Check if user has credits
  82  */
  83 export async function hasCredits(userId: string, amount: number = 1) {
  84   const user = await prisma.user.findUnique({
  85     where: { id: userId },
  86     select: { credits: true },
  87   });
  88 
  89   return (user?.credits || 0) >= amount;
  90 }
