  92 /**
  93  * Deduct credits from user
  94  */
  95 export async function deductCredits(userId: string, amount: number, reason: string) {
  96   const user = await prisma.user.findUnique({
  97     where: { id: userId },
  98     select: { credits: true },
  99   });
 100 
 101   if (!user || user.credits < amount) {
 102     throw new Error('Insufficient credits');
 103   }
 104 
 105   // Update user credits (trigger will log to credit_ledger)
 106   await prisma.user.update({
 107     where: { id: userId },
 108     data: { credits: { decrement: amount } },
 109   });
 110 
 111   return true;
