export function GraphQLProvider({ children }: { children: React.ReactNode }) {
  const { data: session } = useSession();

  const client = useMemo(() => {
    // Create HTTP link with auth headers
    const httpLink = new HttpLink({
      uri: process.env.NEXT_PUBLIC_HASURA_GRAPHQL_URL || 'http://localhost:8080/v1/graphql',
      credentials: 'include',
    });

    // Add auth headers middleware
    const authLink = new ApolloLink((operation, forward) => {
      const headers: Record<string, string> = {};

      // Add JWT token from NextAuth session
      if (session?.user?.id) {
        headers['Authorization'] = `Bearer ${session.user.id}`;
      }

      // Add admin secret if available (for admin operations)
      const adminSecret = process.env.NEXT_PUBLIC_HASURA_ADMIN_SECRET;
      if (adminSecret) {
        headers['x-hasura-admin-secret'] = adminSecret;
      }

      operation.setContext({
        headers: {
          ...operation.getContext().headers,
          ...headers,
        },
      });

      return forward(operation);
    });

    // WebSocket link for subscriptions (only on client)
    const wsLink = typeof window !== 'undefined' ? new GraphQLWsLink(
      createClient({
        url: process.env.NEXT_PUBLIC_HASURA_GRAPHQL_WS_URL || 'ws://localhost:8080/v1/graphql',
        connectionParams: () => {
          const headers: Record<string, string> = {};

          // Add JWT token from NextAuth session
          if (session?.user?.id) {
            headers['Authorization'] = `Bearer ${session.user.id}`;
          }

          // Add admin secret for WebSocket connections
          const adminSecret = process.env.NEXT_PUBLIC_HASURA_ADMIN_SECRET;
          if (adminSecret) {
            headers['x-hasura-admin-secret'] = adminSecret;
          }

          return { headers };
        },
      })
    ) : null;

    // Split based on operation type
    const splitLink = typeof window !== 'undefined' && wsLink
      ? split(
        ({ query }) => {
          const definition = getMainDefinition(query);
          return (
