  15 export async function getPaginatedUsers({ limit, lastVisibleId }: { limit: number, lastVisibleId?: string }) {
  16     let query = adminDb.collection('users')
  17         .orderBy('createdAt', 'desc')
  18         .limit(limit + 1); // Fetch one extra to check for hasNextPage
  19 
  20     if (lastVisibleId) {
  21         const lastDoc = await adminDb.collection('users').doc(lastVisibleId).get();
  22         if (lastDoc.exists) {
  23             query = query.startAfter(lastDoc);
  24         }
  25     }
  26 
  27     const snapshot = await query.get();
  28     const users = snapshot.docs.slice(0, limit).map(doc => ({ id: doc.id, ...doc.data() })) as UserProfile[];
  29     const hasNextPage = snapshot.docs.length > limit;
  30     const newLastVisibleId = hasNextPage ? snapshot.docs[snapshot.docs.length - 2].id : null;
  31 
  32     return { users, hasNextPage, lastVisibleId: newLastVisibleId };
  33 }
