  77 export async function deductUserCredits(userId: string, creditsToDeduct: number): Promise<number> {
  78     const userRef = adminDb.collection('users').doc(userId);
  79 
  80     return await adminDb.runTransaction(async (transaction) => {
  81         const userDoc = await transaction.get(userRef);
  82         if (!userDoc.exists) {
  83             throw new Error("User not found");
  84         }
  85 
  86         const currentCredits = userDoc.data()?.credits ?? 0;
  87 
  88         if (currentCredits < creditsToDeduct) {
  89             throw { status: 402, message: "Insufficient credits. Please purchase more credits to continue." };
  90         }
  91 
  92         const newBalance = currentCredits - creditsToDeduct;
  93         transaction.update(userRef, {
  94             credits: newBalance,
  95             updatedAt: new Date().toISOString()
  96         });
  97 
  98         return newBalance;
  99     });
